fahr_to_kelvin <- function(temp) {
  (temp - 32) * (5 / 9) + 273.15
}
kelvin_to_celsius <- function(temp) {
  temp - 273.15
}
fahr_to_celsius <- function(temp) {
  stopifnot(is.numeric(temp))
  temp_k <- fahr_to_kelvin(temp)
  kelvin_to_celsius(temp_k)
}
fahr_to_celsius(32)

threshold <- 50
for (cont in unique(gapminder$continent)) {
  m <- mean(gapminder[gapminder$continent == cont, "lifeExp"])
  if (m < threshold) {
    cat("Average life expectancy in", cont, "is less than", threshold, "\n")
  } else {
    cat("Average life expectancy in", cont, "is greater than", threshold, "\n")
  }
}

