lower <- 50
upper <- 70
for (ctry in unique(gapminder$country)) {
  m <- mean(gapminder[gapminder$country == ctry, "lifeExp"])
  if (m < lower) {
    cat("Average life expectancy in", ctry, "is less than", lower, "\n")
  } else if (m < upper) {
    cat("Average life expectancy in", ctry, "is between", lower, "and", upper, "\n")
  } else {
    cat("Average life expectancy in", ctry, "is greater than", upper, "\n")
  }
}

